//! Die eine Beschreibung der API — Quelle für `/api` und `/api/endpunkte`.

use serde::Serialize;

#[derive(Debug, Clone, Copy, Serialize, utoipa::ToSchema)]
pub struct Endpunkt {
    pub methode: &'static str,
    pub pfad: &'static str,
    /// braucht `X-KanbanD-Wer`
    pub wer: bool,
    pub thema: &'static str,
    pub zweck: &'static str,
}

const fn e(methode: &'static str, pfad: &'static str, wer: bool, thema: &'static str, zweck: &'static str) -> Endpunkt {
    Endpunkt { methode, pfad, wer, thema, zweck }
}

// R00214 (ADR-0035): `braucht` — dieselben Texte in der Endpunktliste und in der OpenAPI-Beschreibung. Makros statt
// Konstanten, weil `concat!` und die Beschreibung der Handler Literale verlangen. Die Meldungen selbst stehen in
// `modell/braucht.rs`; ändert der PO ihren Wortlaut, zieht dieser Text mit.
macro_rules! braucht_lesen {
    () => {
        "jede Aufgabe trägt braucht: [{nummer, titel, erledigt}] — nur lesbar, abgeleitet aus den Labels braucht:<nr> in deren Reihenfolge (ohne Groß/Klein, dieselbe Nummer einmal; andere Form mit dem Präfix bleibt ein gewöhnliches Label); erledigt: die gebrauchte Karte ist archiviert oder liegt auf einem ihrer Boards in dessen letzter Spalte; ohne lesbare Datei titel null, erledigt false"
    };
}
macro_rules! braucht_wartet {
    () => {
        "Filter wartet=ja|nein: ja — mindestens eine Abhängigkeit, die nicht erledigt ist (auch ohne Datei), nein — die übrigen; anderer Wert → 400"
    };
}
macro_rules! braucht_tuer {
    () => {
        "Abhängigkeiten über labels (braucht:<nr>, die Karte wartet auf #nr): neu hinzukommende braucht:-Labels prüft kanbanD an der Tür, unverändert mitgeschickte nicht — je 400, nichts wird geschrieben: andere Form mit dem Präfix („braucht: erwartet eine Kartennummer (braucht:12)“), Selbstbezug („#n kann nicht auf sich selbst warten“), Nummer ohne Aufgabendatei im Ordner, archivierte zählen als vorhanden („Aufgabe #n gibt es nicht (braucht:n)“), Kreis über alle Aufgaben des Ordners nach dem Schreiben („braucht:n ergäbe einen Kreis: #a → #b → #a“); das Feld braucht ist nur lesbar — braucht im Rumpf (auch braucht: null oder [], vor R00214 stumm übergangen) → 400 „braucht über labels setzen (braucht:<nr>)“"
    };
}
pub(crate) use {braucht_lesen, braucht_tuer, braucht_wartet};

/// Zweck von `GET /api/instanz` — derselbe Text in der Endpunktliste und in der OpenAPI-Beschreibung.
pub const INSTANZ: &str = "diese Instanz {ordner, port, version}: der bediente Ordner absolut und kanonisch (wie in /api/zustand), der gebundene Port (bei belegtem Port der, auf den das Programm ausgewichen ist) und die Programmversion — daran erkennt ein Agent seine Instanz; liest den Ordner nicht und antwortet auch, wenn /api/zustand scheitert";

